module div_8bit(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, input res_ready, output reg res_valid, output reg [15:0] result
);
// Internal registers
reg [7:0] DIVIDEND_REG;
reg [7:0] DIVISOR_REG;
reg [7:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] CNT;
reg START_CNT;
// Sequential logic for updating internal registers
always @(posedge clk) begin
    if (rst == 1'b1) begin
        DIVIDEND_REG <= 8'h0;
        DIVISOR_REG <= 8'h0;
    end else if ((opn_valid == 1'b1) && (res_valid == 1'b0)) begin
        DIVIDEND_REG <= dividend;
        DIVISOR_REG <= divisor;
    end
end
always @(posedge clk) begin
    if (rst == 1'b1) begin
        NEG_DIVISOR <= 8'h0;
    end else if ((opn_valid == 1'b1) && (res_valid == 1'b0)) begin
        NEG_DIVISOR <= ~DIVISOR_REG + 1;
    end
end
always @(posedge clk) begin
    if (rst == 1'b1) begin
        CNT <= 4'h0;
        START_CNT <= 1'b0;
    end else if ((opn_valid == 1'b1) && (res_valid == 1'b0)) begin
        CNT <= 4'h1;
        START_CNT <= 1'b1;
    end else if ((START_CNT == 1'b1) && (CNT[3] == 1'b1)) begin
        CNT <= 4'h0;
        START_CNT <= 1'b0;
    end
end
always @(posedge clk) begin
    if (rst == 1'b1) begin
        SR <= 16'h0;
    end else if ((opn_valid == 1'b1) && (res_valid == 1'b0)) begin
        SR <= {8'h0, DIVIDEND_REG} << 1;
    end else if ((START_CNT == 1'b1) && (CNT != 4'h8)) begin
        SR <= {carry_out, SR[15:1]};
    end
end
// Combinational logic for calculating the remainder and quotient
wire [8:0] temp_result;
wire [7:0] mux_output;
assign temp_result = {1'b0, SR[15:8]} + NEG_DIVISOR;
assign mux_output = (temp_result[8]) ? SR[15:8] : temp_result[7:0];
assign carry_out = (temp_result[8]) ? 1'b0 : 1'b1;
// Output logic
always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 1'b0;
    end else if (CNT == 4'h8) begin
        res_valid <= 1'b1;
    end else if (res_valid && res_ready) begin
        res_valid <= 1'b0;
    end
end
always @(posedge clk) begin
    if (CNT == 4'h8) begin
        result <= {mux_output, SR[7:0]};
    end
end
endmodule
